-- 0013 — a trilha de Rust para quem já programa.
--
-- Primeira trilha escrita direto no catálogo, depois que ele saiu do
-- código: não há pasta em src/lib/trilhas/ nem registro em trilhas.js,
-- e é essa a prova de que a migration 0011 entregou o que prometia.
--
-- O público é explícito e molda o conteúdo: quem já programa não
-- precisa de laço nem de condicional, precisa do que Rust tem e a
-- linguagem anterior não tinha. Por isso a etapa 1 é inteira sobre
-- posse e empréstimo, e sintaxe aparece só como o mínimo para rodar
-- código e ler o erro do compilador.
--
-- Quatro etapas porque é onde as curvas de aprendizado mudam de
-- natureza: o modelo de memória, o sistema de tipos, o ecossistema,
-- e concorrência com async. Async fica na última de propósito —
-- é a segunda curva, e começar por ela é o caminho mais curto para
-- desistir.
--
-- As contagens (etapas, grupos, topicos) não são escritas: o gatilho
-- trilha_contagem as recalcula a cada escrita.

insert into public.trilha (id, rotulo, cor, rota, ordem, publicada, conteudo)
values
  ('rust', 'Rust', '#8a4a2d',
   '[[28, 206], [92, 182], [138, 128], [204, 104], [274, 48]]'::jsonb, 30, true,
   '{"ROADMAP": {"id": "rust", "titulo": "Rust", "subtitulo": "Para quem já programa em outra linguagem — quatro etapas", "fonte": null, "etapas": [{"id": "fundamentos", "numero": 1, "titulo": "O modelo de memória", "objetivo": "Escrever e compilar programas que passam pelo borrow checker sem clonar por desespero.", "descricao": "Você já programa, então a sintaxe de Rust vai custar uma tarde. O que custa semanas é outra coisa: Rust pede que você declare, no tipo, quem é dono de cada valor e por quanto tempo. Em quase toda outra linguagem isso é implícito — o coletor de lixo resolve, ou o programa quebra em produção. Aqui o compilador recusa o programa antes. Esta etapa existe para você parar de brigar com o borrow checker e começar a usá-lo: enquanto o reflexo for `.clone()` sempre que der erro, você está escrevendo a sua linguagem antiga com sintaxe de Rust.", "preRequisitos": "Saber programar em qualquer linguagem; ter visto ponteiros ou referências alguma vez ajuda, mas não é obrigatório.", "duracao": "2 a 4 semanas", "grupos": [{"id": "g-rs-partida", "titulo": "A partida", "descricao": "O suficiente para rodar código e ler o erro do compilador.", "topicos": [{"id": "rs-01", "titulo": "Instalar e rodar", "prioridade": "fundamental", "desc": "rustup, toolchain stable, cargo new, cargo run, rust-analyzer.", "detalhe": "Instale pelo `rustup`, nunca pelo gerenciador de pacotes do sistema: é ele que troca de toolchain, instala alvos de compilação e atualiza o compilador sem quebrar nada. Crie o primeiro projeto com `cargo new` e rode com `cargo run` — em Rust ninguém chama `rustc` na mão fora de exemplo de aula. Instale o rust-analyzer no editor antes de escrever a primeira linha: metade do aprendizado aqui é ver o tipo inferido aparecer ao lado da variável."}, {"id": "rs-02", "titulo": "Ler o erro do compilador", "prioridade": "fundamental", "desc": "Código do erro, cargo explain, a seta que aponta o move, notas e sugestões.", "detalhe": "O compilador de Rust é material didático disfarçado de ferramenta. Cada erro tem um código (`E0382`) que `rustc --explain E0382` desenvolve com exemplo, e o diagnóstico costuma mostrar as três linhas que importam: onde o valor nasceu, onde ele foi movido e onde você tentou usá-lo depois. O erro típico de quem vem de fora é bater o olho na primeira linha vermelha e sair tentando coisas. Leia até o fim, inclusive o `help:` — em boa parte dos casos ele já escreveu a correção."}, {"id": "rs-03", "titulo": "Variáveis, mutabilidade e shadowing", "prioridade": "fundamental", "desc": "let, let mut, const, shadowing, inferência de tipo.", "detalhe": "Imutável é o padrão, e isso não é estilo: é o que torna o resto do modelo verificável. `let mut` só quando você for realmente reatribuir. Shadowing (`let x = x.trim();`) parece mutação mas é um segundo `x`, possivelmente de outro tipo — é idiomático e serve justamente para converter sem inventar nome novo. Se você escreve `mut` em tudo por reflexo, vai sentir depois, quando o empréstimo mutável único começar a doer sem motivo real."}, {"id": "rs-04", "titulo": "Tipos escalares e compostos", "prioridade": "fundamental", "desc": "Inteiros com sinal e tamanho, f64, bool, char, tuplas, arrays.", "detalhe": "Em Rust o tamanho do inteiro está no tipo (`i32`, `u8`, `usize`) e não há conversão implícita: somar `i32` com `usize` não compila, e isso é proposital. `usize` é o tipo de índice e de tamanho — vai aparecer em todo `len()`. Estouro de inteiro aborta em debug e dá a volta em release, então, quando o estouro for possível de verdade, use `checked_add` e `saturating_add` em vez de confiar na sorte. `char` tem 4 bytes e é um ponto de código Unicode, não um byte."}, {"id": "rs-05", "titulo": "Funções e controle de fluxo", "prioridade": "fundamental", "desc": "fn, expressão vs. instrução, if como expressão, loop/while/for, return implícito.", "detalhe": "Quase tudo em Rust é expressão: `if`, `match` e blocos `{}` devolvem valor, e é por isso que a última linha de uma função não leva `return` nem ponto e vírgula. Colocar o ponto e vírgula transforma a expressão em instrução e devolve `()` — é o erro de tipo mais comum da primeira semana, e o compilador descreve exatamente isso quando aponta para o seu `;`. `loop` com `break valor` é a forma de escrever retentativa sem variável acumuladora fora do laço."}]}, {"id": "g-rs-posse", "titulo": "Posse, empréstimo e tempo de vida", "descricao": "O coração da linguagem. Nada depois disso faz sentido sem isso.", "topicos": [{"id": "rs-06", "titulo": "Stack, heap e por que importa aqui", "prioridade": "importante", "desc": "Tamanho conhecido em compilação, Box, custo de cópia, o que significa um valor sair de escopo.", "detalhe": "Você não precisa de um curso de arquitetura, mas precisa deste par: valor de tamanho conhecido vive na pilha e é barato; valor que cresce (uma `String`, um `Vec`) guarda os dados no heap e mantém na pilha um ponteiro, um tamanho e uma capacidade. Posse é, literalmente, quem libera esse heap quando o escopo acaba. Quem entende isso para de achar que `move` é uma regra arbitrária do compilador e passa a ver a liberação dupla que ela está impedindo."}, {"id": "rs-07", "titulo": "Posse e movimento", "prioridade": "fundamental", "desc": "Dono único, move na atribuição e na chamada, Copy vs. Drop, devolver a posse.", "detalhe": "Todo valor tem exatamente um dono; quando o dono sai de escopo, o valor é liberado. Atribuir ou passar para uma função *move* a posse — o nome antigo deixa de ser utilizável, e é daí que vem o `value borrowed here after move`. Tipos escalares implementam `Copy` e por isso parecem fugir à regra; `String` e `Vec` não. O reflexo errado é clonar para calar o erro: clone é cópia do heap e tem custo. Antes de clonar, pergunte se a função precisava mesmo da posse ou só queria *olhar* o valor."}, {"id": "rs-08", "titulo": "Empréstimo e referências", "prioridade": "fundamental", "desc": "&T, &mut T, a regra do leitor múltiplo ou escritor único, NLL.", "detalhe": "Emprestar é dar acesso sem transferir a posse. A regra única: em qualquer ponto, ou N referências imutáveis, ou uma mutável — nunca os dois. Isso elimina por construção a classe de bug em que alguém itera sobre uma coleção enquanto outro trecho a modifica. O empréstimo acaba no último uso, não no fim do bloco (é o *non-lexical lifetime*), então às vezes basta mover a linha que usa a referência para cima e o erro some. O sinal de que você entendeu: suas funções passam a receber `&str` e `&[T]` em vez de `String` e `Vec<T>`."}, {"id": "rs-09", "titulo": "Fatias", "prioridade": "fundamental", "desc": "&str vs. String, &[T] vs. Vec<T>, indexação por faixa, UTF-8.", "detalhe": "Fatia é uma referência a um pedaço contíguo de algo que pertence a outro. `&str` é a fatia de texto e deve ser o tipo do parâmetro quase sempre; `String` só quando a função precisa guardar ou crescer. A pegadinha que todo mundo leva: `String` é UTF-8, então `s[0]` não existe e cortar por índice em cima de um caractere multibyte causa pânico em tempo de execução. Para percorrer texto use `.chars()` ou `.bytes()` e decida conscientemente qual dos dois o problema pede."}, {"id": "rs-10", "titulo": "Tempos de vida", "prioridade": "importante", "desc": "''a nas assinaturas, elisão, por que o compilador pede anotação, ''static.", "detalhe": "Tempo de vida não prolonga nada: é só você contando ao compilador qual referência de saída veio de qual referência de entrada. Na maioria das funções as regras de elisão deduzem sozinhas e você nunca escreve `''a`. Quando o compilador pede, é porque há duas entradas emprestadas e ele não sabe de qual a saída depende. Não saia espalhando `''static` para fazer compilar — `''static` significa ''vive até o fim do programa'' e costuma empurrar o problema para quem chama. Struct que guarda referência é o lugar onde isso fica obrigatório, e é também o primeiro lugar onde vale perguntar se não era mais simples guardar o valor."}, {"id": "rs-11", "titulo": "Structs e métodos", "prioridade": "fundamental", "desc": "struct, impl, &self vs. self, construtores associados, derive.", "detalhe": "`impl` separa o dado do comportamento, e o receptor diz tudo: `&self` lê, `&mut self` altera, `self` consome (típico de métodos que transformam e devolvem outro tipo). Rust não tem construtor de linguagem — a convenção é uma função associada `new`. `#[derive(Debug, Clone, PartialEq)]` resolve o que em outras linguagens é código repetitivo; coloque `Debug` em praticamente tudo, porque sem ele você não imprime a struct com `{:?}` no primeiro momento em que precisar."}, {"id": "rs-12", "titulo": "Módulos e visibilidade", "prioridade": "importante", "desc": "mod, pub, use, caminhos, arquivo vs. pasta, crate e workspace.", "detalhe": "A árvore de módulos é declarada, não deduzida da pasta: um arquivo só existe para o compilador quando algum `mod` o nomeia. Tudo é privado por padrão, e privado em Rust significa visível ao módulo e aos filhos dele. `pub(crate)` é o meio-termo que você vai usar muito — exporta para dentro do projeto sem virar API pública. Quem vem de linguagens que importam por caminho de arquivo tropeça aqui uma vez e nunca mais."}]}]}, {"id": "tipos", "numero": 2, "titulo": "Tipos, erros e abstração", "objetivo": "Modelar o domínio com enums e traits de modo que o estado inválido não compile.", "descricao": "Esta é a etapa em que Rust deixa de parecer uma linguagem chata e começa a pagar. O sistema de tipos aqui não é burocracia de declaração: `Option` e `Result` substituem nulo e exceção, enums carregam dados e o `match` obriga você a tratar cada caso. Vindo de outra linguagem, a tentação é traduzir seus padrões antigos — hierarquia de classes com herança, exceções subindo pela pilha, um nulo circulando. Nada disso existe aqui, e as substituições não são piores: são verificadas. Se você sair desta etapa ainda chamando `.unwrap()` em todo lugar, você terá trocado o `NullPointerException` por um pânico.", "preRequisitos": "Etapa 1: posse e empréstimo confortáveis.", "duracao": "3 a 5 semanas", "grupos": [{"id": "g-tp-dados", "titulo": "Modelar com tipos", "topicos": [{"id": "tp-01", "titulo": "Enums com dados", "prioridade": "fundamental", "desc": "Variantes com campos, enum como união marcada, modelar estado.", "detalhe": "O enum de Rust não é um inteiro com nome: cada variante carrega os dados que só fazem sentido nela. É com isso que você faz o estado inválido não compilar — em vez de uma struct com `status`, `erro` e `resultado` onde duas combinações são impossíveis mas representáveis, você escreve três variantes. O sinal de que está indo bem: desaparecem os comentários do tipo ''este campo só vale quando o outro é X''."}, {"id": "tp-02", "titulo": "match e padrões", "prioridade": "fundamental", "desc": "Exaustividade, desestruturação, guardas, binding com @, if let e let else.", "detalhe": "`match` exige que todos os casos sejam cobertos, e essa é a maior rede de proteção da linguagem: acrescente uma variante ao enum e o compilador lista cada lugar que precisa ser atualizado. Por isso, resista ao `_ =>` como atalho — ele desliga exatamente essa checagem. `if let` é o match de um caso só, e `let Some(x) = ... else { return; }` é a forma idiomática de sair cedo sem indentar o resto da função."}, {"id": "tp-03", "titulo": "Option", "prioridade": "fundamental", "desc": "Some/None, map, and_then, unwrap_or, ok_or, ? em Option.", "detalhe": "`Option<T>` é a ausência explicitada no tipo: não existe nulo, então não existe desreferência de nulo. O ganho real não é a segurança, é a obrigação de decidir o que fazer quando não há valor, no lugar onde essa decisão é informada. Aprenda os combinadores — `map`, `and_then`, `unwrap_or_default`, `filter` — porque metade do código que você escreveria com `if` some. `unwrap()` só quando o `None` for impossível por construção e você souber explicar por quê."}, {"id": "tp-04", "titulo": "Result e o operador ?", "prioridade": "fundamental", "desc": "Ok/Err, propagar com ?, From para converter erro, Result em main.", "detalhe": "Rust não tem exceção: falha previsível é valor de retorno. O `?` propaga o `Err` para quem chamou, convertendo o tipo pelo `From` — é isso que faz uma função poder devolver um erro só sendo alimentada por três bibliotecas diferentes. Escreva o caminho feliz com `?` e trate o erro na borda (no `main`, no manipulador HTTP), não em cada camada. Erro engolido com `let _ =` é a única forma de perder uma falha em Rust, e é sempre uma decisão sua."}, {"id": "tp-05", "titulo": "Erros próprios", "prioridade": "importante", "desc": "Tipo de erro do domínio, std::error::Error, thiserror e anyhow, pânico vs. erro.", "detalhe": "Em biblioteca, defina um enum de erro e implemente `Error` — `thiserror` faz isso com uma derive. Em binário, `anyhow::Result` com `.context(\"lendo config\")` costuma bastar e dá mensagens muito melhores do que o erro cru. A linha que separa os dois mundos: `Result` é falha esperada (arquivo não existe, entrada inválida), `panic!` é bug ou invariante quebrada. Usar pânico como controle de fluxo é o jeito de recriar exceções numa linguagem que fez questão de não ter."}, {"id": "tp-06", "titulo": "Coleções", "prioridade": "fundamental", "desc": "Vec, HashMap, HashSet, BTreeMap, VecDeque, a API entry.", "detalhe": "`Vec` e `HashMap` cobrem quase tudo. Vale conhecer `entry()`: `*mapa.entry(chave).or_insert(0) += 1` é o contador em uma linha e evita a busca dupla que você faria com `contains_key` + `insert`. `BTreeMap` quando a ordem das chaves importa. Dica prática de desempenho: `Vec::with_capacity` quando você já sabe o tamanho, porque cada realocação copia tudo."}]}, {"id": "g-tp-abstracao", "titulo": "Abstração sem herança", "topicos": [{"id": "tp-07", "titulo": "Traits", "prioridade": "fundamental", "desc": "Definir e implementar, métodos padrão, a regra do órfão, traits da std.", "detalhe": "Trait é comportamento compartilhado, e substitui a herança que não existe aqui. Implemente `Display` para a saída que o usuário lê e deixe `Debug` para você. A regra do órfão — você só implementa um trait se o trait ou o tipo forem seus — é o que impede duas bibliotecas de implementarem a mesma coisa de formas conflitantes; o contorno idiomático é o *newtype*, uma struct de um campo só em volta do tipo alheio."}, {"id": "tp-08", "titulo": "Genéricos e limites", "prioridade": "fundamental", "desc": "<T>, where, impl Trait em argumento e em retorno, monomorfização.", "detalhe": "Genérico em Rust não tem custo em tempo de execução: o compilador gera uma cópia por tipo concreto usado. O preço aparece no tempo de compilação e no tamanho do binário, não na velocidade. Comece aceitando `impl Trait` nos parâmetros (`fn imprime(x: impl Display)`) e só caia no `<T: ...>` explícito quando precisar nomear o tipo em mais de um lugar. `where` existe para a assinatura continuar legível quando os limites crescem."}, {"id": "tp-09", "titulo": "Despacho dinâmico", "prioridade": "importante", "desc": "dyn Trait, Box<dyn Trait>, object safety, quando vale trocar estático por dinâmico.", "detalhe": "`Box<dyn Trait>` é o que você usa quando o tipo concreto só é conhecido em tempo de execução — uma lista de manipuladores heterogêneos, um plugue escolhido por configuração. Custa uma indireção e impede inline. Quem vem de linguagem orientada a objetos tende a começar por `dyn` porque parece familiar; em Rust o padrão é o genérico, e `dyn` é a exceção escolhida. Nem todo trait pode virar objeto: método genérico ou que devolva `Self` quebra a *object safety*, e o erro do compilador diz qual."}, {"id": "tp-10", "titulo": "Iteradores", "prioridade": "fundamental", "desc": "Iterator, map/filter/fold, collect, lazy, into_iter vs. iter vs. iter_mut.", "detalhe": "Iterador é a abstração mais usada da linguagem, e é preguiçoso: nada acontece até um `collect`, um `sum` ou um `for`. Encadear adaptadores compila para algo tão rápido quanto o laço escrito à mão — não há penalidade por escrever bonito. A distinção que confunde no começo: `iter()` empresta, `iter_mut()` empresta mutável, `into_iter()` consome a coleção. Implementar `Iterator` para um tipo seu é um exercício que ensina mais sobre a linguagem do que parece."}, {"id": "tp-11", "titulo": "Closures", "prioridade": "importante", "desc": "Fn, FnMut, FnOnce, captura por referência e por move, closure como argumento.", "detalhe": "Uma closure captura o ambiente, e o trait que ela implementa depende de *como*: só lê (`Fn`), altera (`FnMut`) ou consome (`FnOnce`). Você raramente escreve isso à mão, mas precisa ler a assinatura quando o compilador reclama. `move` força a captura por posse e é obrigatório quando a closure sobrevive ao escopo onde nasceu — é a primeira coisa que você vai aprender de novo, sob pressão, ao criar uma thread."}, {"id": "tp-12", "titulo": "Smart pointers", "prioridade": "importante", "desc": "Box, Rc, RefCell, mutabilidade interior, Deref e Drop, Weak e ciclos.", "detalhe": "`Box` é posse no heap e resolve o tipo recursivo (a árvore, a lista). `Rc` é posse compartilhada por contagem, para um grafo em que ninguém é o dono óbvio. `RefCell` move a checagem de empréstimo para o tempo de execução — e com isso o erro vira pânico, então use quando o compartilhamento for real e não para fugir do borrow checker. `Rc<RefCell<T>>` em tudo é o cheiro clássico de um modelo de dados que ainda não foi pensado em termos de posse; às vezes a resposta certa é um `Vec` com índices."}, {"id": "tp-13", "titulo": "Conversões", "prioridade": "opcional", "desc": "From/Into, TryFrom, AsRef, Deref coercion, parse e FromStr.", "detalhe": "Implemente `From` e ganhe `Into` de graça — e ganhe também a conversão automática do `?` entre os seus tipos de erro. `TryFrom` é a versão que pode falhar, para conversão estreitando valor. `AsRef<str>` nos parâmetros aceita `String` e `&str` sem obrigar quem chama a converter. Entender a coerção de `Deref` explica por que `&String` funciona onde se pede `&str`, que até aqui parecia mágica."}]}]}, {"id": "pratica", "numero": 3, "titulo": "Programa de verdade", "objetivo": "Entregar um binário testado, com dependências, I/O e erros tratados, que outra pessoa consiga rodar.", "descricao": "Até aqui foram exercícios. Esta etapa é o que separa quem fez tutorial de quem usa a linguagem: cargo e o ecossistema, teste junto do código, serialização, entrada e saída, e as decisões chatas de empacotar e publicar. É também onde você descobre que boa parte da ''biblioteca padrão'' de Rust mora no crates.io por decisão de projeto — não espere achar cliente HTTP, geração de número aleatório ou data e hora na std.", "preRequisitos": "Etapas 1 e 2.", "duracao": "3 a 4 semanas", "grupos": [{"id": "g-pr-ferramentas", "titulo": "Cargo e o ecossistema", "topicos": [{"id": "pr-01", "titulo": "Cargo a sério", "prioridade": "fundamental", "desc": "Cargo.toml, Cargo.lock, perfis debug e release, features, workspace.", "detalhe": "Cargo é gerenciador de pacotes, sistema de build e executor de testes no mesmo comando — aprenda-o de verdade cedo. Dois pontos que custam tempo quando ignorados: código em debug pode ser dez vezes mais lento, então qualquer medição de desempenho é em `--release`; e `Cargo.lock` se versiona em binário e não em biblioteca. *Features* são o mecanismo de compilação condicional das dependências e é por elas que você desliga metade de um crate que não vai usar."}, {"id": "pr-02", "titulo": "Formatação e lint", "prioridade": "fundamental", "desc": "cargo fmt, clippy, allow/deny, CI.", "detalhe": "`cargo fmt` acabou com a discussão de estilo em Rust: aceite o padrão e siga. `cargo clippy` é mais do que um lint — ele ensina idioma, apontando o `match` que era um `if let`, o `&String` que era `&str`, o `clone` que não precisava. Rode os dois no CI com `-D warnings` desde o primeiro dia; tolerar aviso é como a dívida cresce silenciosa aqui."}, {"id": "pr-03", "titulo": "Testes", "prioridade": "fundamental", "desc": "#[test], mod tests, assert_eq, testes de integração em tests/, doc tests.", "detalhe": "Teste de unidade mora no mesmo arquivo do código, num `mod tests` com `#[cfg(test)]`, e por isso enxerga as funções privadas. Teste de integração vai em `tests/` e só vê a API pública — se ele ficar difícil de escrever, isso é informação sobre a sua API. O detalhe bonito: exemplos nos comentários `///` são compilados e executados por `cargo test`, então documentação desatualizada em Rust quebra o build."}, {"id": "pr-04", "titulo": "Escolher dependência", "prioridade": "importante", "desc": "crates.io, docs.rs, versões semânticas, cargo add, cargo audit, peso de árvore.", "detalhe": "A std é deliberadamente pequena: data (`chrono`/`time`), aleatoriedade (`rand`), HTTP (`reqwest`), serialização (`serde`), regex, tudo vem de fora. Antes de adicionar, abra o docs.rs e olhe três coisas: data da última publicação, número de dependências que ela arrasta e se ela usa `unsafe`. Árvore de dependências grande é o principal motivo de compilação lenta, e é um custo que você não recupera depois."}, {"id": "pr-05", "titulo": "Documentar", "prioridade": "opcional", "desc": "///, //!, cargo doc, exemplos executáveis, README como doc.", "detalhe": "Documentação em Rust é código: o exemplo no comentário roda nos testes e a saída do `cargo doc` é a mesma coisa que você lê no docs.rs. Escreva o exemplo antes da prosa — ele mostra a ergonomia da API e, muitas vezes, revela que a assinatura está errada antes de você ter usuários."}]}, {"id": "g-pr-mundo", "titulo": "Falar com o mundo", "topicos": [{"id": "pr-06", "titulo": "Entrada e saída", "prioridade": "fundamental", "desc": "std::fs, Read/Write, BufReader e BufWriter, caminhos com Path e PathBuf.", "detalhe": "`fs::read_to_string` resolve o caso simples; para arquivo grande, leia linha a linha com `BufReader`, senão você carrega tudo na memória. Escrever sem `BufWriter` faz uma chamada de sistema por `write!` e fica absurdamente lento — é a causa número um de ''Rust ficou mais devagar que Python'' em exercício de benchmark. `Path`/`PathBuf` em vez de `String` para caminho: eles conhecem separador e componentes."}, {"id": "pr-07", "titulo": "Linha de comando", "prioridade": "importante", "desc": "std::env::args, clap com derive, código de saída, stdout vs. stderr.", "detalhe": "Para qualquer coisa além de um argumento, use `clap` com a derive: você descreve a struct dos argumentos e ganha parsing, `--help` e mensagens de erro. Mande resultado para stdout e diagnóstico para stderr — é isso que permite o seu programa entrar num pipe. Devolva código de saída diferente de zero na falha; `fn main() -> Result<...>` já faz isso e ainda imprime o erro."}, {"id": "pr-08", "titulo": "Serialização com serde", "prioridade": "fundamental", "desc": "Serialize/Deserialize, serde_json, atributos de renomear e pular, campos opcionais.", "detalhe": "`serde` é o crate mais onipresente do ecossistema e vale conhecer os atributos: `#[serde(rename_all = \"camelCase\")]`, `default`, `skip_serializing_if`. A vantagem sobre o que você fazia antes é que JSON malformado vira `Err` tipado na borda, não um campo faltando que explode três camadas adiante. Use `Option<T>` para campo que pode não vir e seja explícito sobre o que é obrigatório — o tipo vira a especificação do formato."}, {"id": "pr-09", "titulo": "Logging e diagnóstico", "prioridade": "importante", "desc": "log e env_logger, tracing, níveis, dbg! vs. println!.", "detalhe": "`dbg!(x)` imprime arquivo, linha, expressão e valor, e devolve o valor — é melhor que `println!` para depuração e fácil de caçar depois. Para o programa de verdade, use `tracing` com `tracing-subscriber`: níveis configuráveis por variável de ambiente e, quando você chegar em async, *spans* que mantêm o contexto que um log de linha solta perde."}, {"id": "pr-10", "titulo": "Projeto que você termina", "prioridade": "fundamental", "desc": "Escopo pequeno, README, teste, release, publicar ou distribuir o binário.", "detalhe": "Escolha algo pequeno e seu — um organizador de arquivos, um cliente de uma API que você usa, um parser do formato esquisito do seu trabalho. O valor não está no código: está em passar pelas etapas chatas (argumentos, erro legível, teste, binário que roda na máquina de outra pessoa) uma vez inteira. Quem pula isso acumula conhecimento de sintaxe sem nunca ter tomado uma decisão de API."}, {"id": "pr-11", "titulo": "Interoperar e compilar para outros alvos", "prioridade": "opcional", "desc": "extern \"C\", #[no_mangle], bindgen, cross, musl, wasm32.", "detalhe": "Rust foi feito para conviver com C, e `rustup target add` mais `cross` resolvem a compilação cruzada que em outras linguagens é um projeto à parte. Alvo `musl` dá binário estático que roda em container `scratch`; `wasm32-unknown-unknown` com `wasm-bindgen` leva o mesmo código para o navegador. Ponto de atenção: toda fronteira FFI é `unsafe`, porque do outro lado não há quem garanta as invariantes."}]}]}, {"id": "avancado", "numero": 4, "titulo": "Concorrência, async e desempenho", "objetivo": "Escrever código concorrente que o compilador aceita e medir antes de otimizar.", "descricao": "A promessa que fez Rust sair do nicho é esta: concorrência sem corrida de dados, verificada em tempo de compilação. Os traits `Send` e `Sync` transformam em erro de tipo a classe de bug que em outras linguagens só aparece em produção sob carga. Depois vem async, que é uma segunda curva de aprendizado — e a parte onde mais gente trava, porque o modelo é diferente de threads e as mensagens de erro ficam longas. No fim, desempenho: a etapa em que você mede antes de mexer, porque Rust já é rápido e a intuição aqui erra muito.", "preRequisitos": "Etapas 1 a 3, e pelo menos um projeto terminado.", "duracao": "4 a 6 semanas", "grupos": [{"id": "g-av-concorrencia", "titulo": "Concorrência", "topicos": [{"id": "av-01", "titulo": "Threads e canais", "prioridade": "fundamental", "desc": "thread::spawn, join, move na closure, mpsc, escopo com thread::scope.", "detalhe": "`thread::spawn` pede `move` porque a thread pode sobreviver à função que a criou — o compilador não deixa você emprestar uma variável local para ela. `thread::scope` é a saída quando as threads terminam antes do escopo: aí emprestar passa a ser legal. Canais `mpsc` dão o modelo de passar mensagem em vez de compartilhar estado, que continua sendo o desenho mais simples de acertar."}, {"id": "av-02", "titulo": "Send e Sync", "prioridade": "fundamental", "desc": "O que cada um significa, por que Rc não é Send, auto traits, o erro que você vai ver.", "detalhe": "`Send` é ''pode ser movido para outra thread''; `Sync` é ''&T pode ser compartilhado entre threads''. Eles são deduzidos automaticamente, e é por isso que você nunca os escreve mas vive lendo sobre eles nos erros. O caso didático: `Rc` não é `Send` porque sua contagem não é atômica; se duas threads a incrementassem ao mesmo tempo, você teria liberação dupla. Em Rust isso simplesmente não compila — troque por `Arc` e siga."}, {"id": "av-03", "titulo": "Estado compartilhado", "prioridade": "fundamental", "desc": "Arc, Mutex, RwLock, atômicos, deadlock, envenenamento de lock.", "detalhe": "`Arc<Mutex<T>>` é o par padrão: contagem atômica para compartilhar, exclusão mútua para alterar. O `lock()` devolve `Result` porque uma thread que entrou em pânico segurando o lock o *envenena* — e isso é informação, não burocracia. O risco que a linguagem não elimina é o deadlock: ordem de aquisição diferente em dois lugares trava igual em qualquer linguagem. Mantenha a seção crítica curta e nunca chame função desconhecida com o lock na mão."}, {"id": "av-04", "titulo": "Paralelismo de dados", "prioridade": "importante", "desc": "rayon, par_iter, quando paralelizar não compensa, redução.", "detalhe": "`rayon` transforma `iter()` em `par_iter()` e paraleliza o laço; na prática é a melhor relação entre esforço e ganho da linguagem. Mas só compensa quando o trabalho por item é grande o bastante para pagar a coordenação — paralelizar um `map` que soma dois inteiros deixa o programa mais lento, e esse é um experimento que vale fazer uma vez para ganhar a intuição."}]}, {"id": "g-av-async", "titulo": "Async", "topicos": [{"id": "av-05", "titulo": "Como async funciona", "prioridade": "fundamental", "desc": "Future preguiçoso, poll, async/await, a necessidade de um runtime.", "detalhe": "Uma `Future` em Rust não faz nada até ser consultada — chamar uma função `async` sem `.await` não executa coisa alguma, e o compilador avisa com um `unused` que é fácil ignorar. Não há runtime embutido na linguagem: você escolhe (`tokio`, na prática) e ele agenda as tarefas. Entender que `async` é uma máquina de estados gerada pelo compilador explica quase todas as mensagens de erro estranhas que virão."}, {"id": "av-06", "titulo": "Tokio na prática", "prioridade": "fundamental", "desc": "#[tokio::main], spawn, join! e select!, canais async, tarefas bloqueantes.", "detalhe": "`tokio::spawn` cria tarefa, não thread — milhares delas cabem num punhado de threads. A regra que mais gente quebra: nunca bloqueie dentro de uma tarefa async. Uma leitura síncrona de arquivo, um `thread::sleep` ou um cálculo pesado travam a thread do executor e a latência de tudo mais desaba; para isso existe `spawn_blocking`. `select!` espera o primeiro de vários e é como se escreve timeout e cancelamento."}, {"id": "av-07", "titulo": "Async que dá trabalho", "prioridade": "importante", "desc": "Send em tarefa, Pin e Box::pin, async em trait, cancelamento, erros longos.", "detalhe": "É aqui que você perde uma tarde. Erro de tarefa que não é `Send` quase sempre significa que um `MutexGuard` ou um `Rc` atravessou um `.await` — a correção costuma ser fechar o escopo antes de esperar. `Pin` aparece porque a máquina de estados pode se referenciar; na prática você escreve `Box::pin` e segue. Cancelar em Rust é largar a future, então o que estava no meio simplesmente não acontece: saiba quais dos seus pontos de `.await` não podem ser interrompidos pela metade."}, {"id": "av-08", "titulo": "Um serviço de rede", "prioridade": "importante", "desc": "axum ou similar, handlers, estado compartilhado, sqlx, desligamento gracioso.", "detalhe": "Juntar tudo num serviço HTTP é o exercício que prova a etapa: `axum` para rotas, estado em `Arc`, `sqlx` com consultas verificadas contra o banco em tempo de compilação, e um desligamento que espera as requisições em voo. É também onde o investimento nas etapas anteriores aparece de uma vez — o tipo do erro, o `?`, o `serde` e o `Send` passam a trabalhar juntos."}]}, {"id": "g-av-desempenho", "titulo": "Desempenho e os cantos escuros", "topicos": [{"id": "av-09", "titulo": "Medir antes de otimizar", "prioridade": "fundamental", "desc": "criterion, flamegraph, perfil em release, alocação como suspeita principal.", "detalhe": "Meça sempre em `--release` e com `criterion`, que roda repetições e trata a variância — cronometrar à mão em Rust mede quase sempre o ruído. Quando perfilar, procure primeiro por alocação em laço, `clone` desnecessário, `String` onde cabia `&str` e `collect` intermediário que podia ter ficado preguiçoso. A intuição de desempenho que você trouxe de linguagem com coletor de lixo não transfere bem."}, {"id": "av-10", "titulo": "unsafe com responsabilidade", "prioridade": "opcional", "desc": "O que unsafe libera, invariantes, encapsular em API segura, miri.", "detalhe": "`unsafe` não desliga o borrow checker: libera cinco coisas específicas, como desreferenciar ponteiro cru e chamar função externa. Ele não é passe livre — é você assumindo a prova que o compilador fazia. A prática correta é um bloco mínimo embrulhado numa API segura, com um comentário `// SAFETY:` dizendo qual invariante o torna válido, e `cargo miri test` para pegar o comportamento indefinido que o teste normal não pega. Se você está escrevendo `unsafe` no primeiro ano, quase sempre há uma solução segura que você ainda não conhece."}, {"id": "av-11", "titulo": "Macros", "prioridade": "opcional", "desc": "macro_rules!, derive procedural, cargo expand, quando não vale.", "detalhe": "`macro_rules!` resolve repetição que genérico não alcança, como gerar um `impl` para uma lista de tipos. Macro procedural é um crate separado que recebe e devolve tokens — é como `serde` e `thiserror` funcionam. Custo real: macro atrapalha o rust-analyzer, esconde o código de quem lê e piora a mensagem de erro. Use `cargo expand` para ver o que foi gerado antes de culpar o compilador."}, {"id": "av-12", "titulo": "Ler código alheio", "prioridade": "importante", "desc": "Fonte da std, crates bem escritos, RFCs, Rustonomicon, edições.", "detalhe": "A std de Rust é legível e está toda a um clique no docs.rs — ver como `Option::map` é implementado ensina mais do que um capítulo. Acompanhe as edições (2015, 2018, 2021, 2024): elas mudam o idioma sem quebrar compatibilidade, e código antigo da internet pode estar desatualizado sem estar errado. O Rustonomicon é a leitura certa no dia, e só no dia, em que `unsafe` virar necessidade."}]}]}]}, "PROJETOS": {"fundamentos": ["Reescrever um script seu de ~100 linhas (de Python, JS ou Go) em Rust, sem usar `.clone()` nenhuma vez — e, para cada clone que você quase escreveu, anotar o que o compilador estava tentando dizer.", "Implementar uma lista encadeada simples com `Box` e descobrir, na prática, por que esse exercício é famoso por ser difícil em Rust.", "Escrever um contador de palavras que lê um arquivo e imprime as 10 mais frequentes, com todas as funções recebendo `&str` e `&[T]`."], "tipos": ["Modelar uma máquina de estados do seu domínio (pedido, assinatura, partida de jogo) como enum, de modo que nenhuma transição inválida compile.", "Escrever um parser de um formato pequeno (INI, CSV simplificado, expressão aritmética) devolvendo `Result` com um tipo de erro próprio — sem nenhum `unwrap` fora dos testes.", "Implementar `Iterator` para um tipo seu e usá-lo numa cadeia de `filter`/`map`/`fold`."], "pratica": ["Publicar uma ferramenta de linha de comando com `clap`, testes de integração em `tests/`, README e um binário de release que roda na máquina de outra pessoa.", "Consumir uma API pública com `reqwest` + `serde`, com erro tratado e mensagem legível quando a rede cai ou o JSON muda.", "Colocar `fmt`, `clippy -D warnings` e `test` num CI e deixar a build vermelha até estar tudo limpo."], "avancado": ["Paralelizar o processamento de um diretório de arquivos com `rayon` e medir com `criterion` o ponto em que paralelizar passa a compensar.", "Escrever um serviço HTTP com `axum` que guarda estado em `Arc<Mutex<_>>` ou num banco via `sqlx`, com desligamento gracioso.", "Fazer um rastreador concorrente com `tokio` limitado por semáforo, e explicar por escrito o que acontece com as requisições em voo quando ele é cancelado."]}, "RECURSOS": [{"etapa": "fundamentos", "titulo": "The Rust Programming Language (o Livro)", "url": "https://doc.rust-lang.org/book/", "nota": "A referência oficial; capítulos 1 a 10 cobrem esta etapa"}, {"etapa": "fundamentos", "titulo": "Rust by Example", "url": "https://doc.rust-lang.org/rust-by-example/", "nota": "Exemplos executáveis, bom para quem já programa"}, {"etapa": "fundamentos", "titulo": "Rustlings", "url": "https://github.com/rust-lang/rustlings", "nota": "Exercícios pequenos corrigidos pelo compilador"}, {"etapa": "fundamentos", "titulo": "Comprehensive Rust — Google", "url": "https://google.github.io/comprehensive-rust/", "nota": "Curso intensivo para quem vem de outra linguagem"}, {"etapa": "tipos", "titulo": "Rust API Guidelines", "url": "https://rust-lang.github.io/api-guidelines/", "nota": "Como nomear e desenhar API idiomática"}, {"etapa": "tipos", "titulo": "Learning Rust With Entirely Too Many Linked Lists", "url": "https://rust-unofficial.github.io/too-many-lists/", "nota": "Posse, Box, Rc e RefCell levados a sério"}, {"etapa": "tipos", "titulo": "Error Handling in Rust — Andrew Gallant", "url": "https://blog.burntsushi.net/rust-error-handling/", "nota": "Result, From e tipos de erro próprios"}, {"etapa": "pratica", "titulo": "The Cargo Book", "url": "https://doc.rust-lang.org/cargo/", "nota": "Perfis, features e workspaces"}, {"etapa": "pratica", "titulo": "docs.rs", "url": "https://docs.rs/", "nota": "Documentação de todo crate publicado"}, {"etapa": "pratica", "titulo": "Command Line Applications in Rust", "url": "https://rust-cli.github.io/book/", "nota": "CLI, argumentos e erro legível"}, {"etapa": "pratica", "titulo": "Zero To Production In Rust — Luca Palmieri", "url": "https://www.zero2prod.com/", "nota": "Projeto inteiro, do teste ao deploy"}, {"etapa": "avancado", "titulo": "Tokio Tutorial", "url": "https://tokio.rs/tokio/tutorial", "nota": "Async na prática"}, {"etapa": "avancado", "titulo": "Asynchronous Programming in Rust", "url": "https://rust-lang.github.io/async-book/", "nota": "Future, poll e o modelo por baixo"}, {"etapa": "avancado", "titulo": "The Rustonomicon", "url": "https://doc.rust-lang.org/nomicon/", "nota": "unsafe e as invariantes — só quando precisar"}, {"etapa": "avancado", "titulo": "The Rust Performance Book", "url": "https://nnethercote.github.io/perf-book/", "nota": "Medir, perfilar e reduzir alocação"}], "LEGENDA": [{"chave": "fundamental", "rotulo": "Fundamental", "desc": "Ordem estrita. Não pule."}, {"chave": "importante", "rotulo": "Importante", "desc": "Recomendado, mas a ordem é flexível."}, {"chave": "opcional", "rotulo": "Opcional", "desc": "Pule sem culpa e volte depois."}], "ESTADOS": [{"chave": "pendente", "rotulo": "Pendente"}, {"chave": "estudando", "rotulo": "Estudando"}, {"chave": "feito", "rotulo": "Feito"}, {"chave": "pulado", "rotulo": "Pulado"}], "CRITERIOS": ["Ler um erro do borrow checker e dizer qual é o problema de posse antes de tentar qualquer correção.", "Escrever a assinatura de uma função decidindo conscientemente entre posse, &T e &mut T — e saber justificar a escolha.", "Modelar um estado do seu domínio com enum e match de modo que a combinação inválida não compile.", "Terminar e distribuir um binário com testes, erro legível e dependências escolhidas com critério.", "Explicar por que um trecho concorrente não compila em termos de Send e Sync, e corrigi-lo sem recorrer a unsafe."]}'::jsonb);
